const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
};

const premiumForItem = (item: Item): number => {
  const basePremium = BASE_PREMIUM_BY_ITEM_TYPE[item.type];
  return basePremium + basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
};

const premiumForItems = (items: Item[]): number =>
  items.reduce((total, item) => total + premiumForItem(item), 0);
